insert into public.iskra_shared_kb (topic, topic_norm, body, tags) values
  ('Сколько белка нужно в день', public.iskra_kb_norm('Сколько белка нужно в день'), 'Взрослому без спорта — примерно 0,8–1 г белка на килограмм веса. При силовых тренировках — 1,6–2 г. Белок есть в яйцах, мясе, рыбе, твороге, бобовых, орехах. Распределяй по приёмам пищи, а не одной порцией вечером: организму нужно 20–40 г за раз. Больше нормы здоровым людям не нужно, и «белковый удар» не ускоряет рост мышц.', 'питание, белок, еда, спорт'),
  ('Сколько воды пить в день', public.iskra_kb_norm('Сколько воды пить в день'), 'Ориентир — около 30 мл на килограмм веса, то есть 1,5–2,5 литра в день вместе с чаем, кофе и супом. Летом, при жаре и тренировках — больше. Хороший индикатор — жажда и цвет мочи: светло-жёлтая значит достаточно. Насильно вливать воду не надо: избыток тоже вреден. Пожилым жажда приходит позже, поэтому им стоит пить по напоминанию.', 'питание, вода, питьё'),
  ('Сколько сахара безопасно', public.iskra_kb_norm('Сколько сахара безопасно'), 'Всемирная организация здравоохранения советует держать добавленный сахар ниже 10% калорий, а лучше ниже 5% — это около 25 г, то есть 5–6 чайных ложек в день. Сахар прячется в соусах, йогуртах, соках, хлопьях. На этикетке смотри строку «углеводы, из них сахара». Фрукт целиком — не то же самое, что сок: там клетчатка и нет добавленного сахара.', 'питание, сахар, сладкое'),
  ('Сколько соли в день', public.iskra_kb_norm('Сколько соли в день'), 'ВОЗ рекомендует не больше 5 г соли в сутки — это примерно чайная ложка и около 2 г натрия. Большая часть соли приходит не из солонки, а из готовой еды: хлеба, колбасы, сыра, соусов, консервов. Соли в конце готовки и меньше: вкус чувствуется сильнее. Вместо соли работают специи, лимон, чеснок, травы.', 'питание, соль'),
  ('Что такое калории', public.iskra_kb_norm('Что такое калории'), 'Калория — единица энергии. В грамме белка и углеводов около 4 ккал, в грамме жира — 9. Организм тратит энергию на базовый обмен, движение и переваривание. Чтобы худеть, нужен дефицит 300–500 ккал в день — это примерно 0,3–0,5 кг в неделю. Считать каждую крошку не обязательно: достаточно понять размер порций за пару недель и убрать лишнее.', 'питание, калории, вес'),
  ('Почему жёсткие диеты не работают', public.iskra_kb_norm('Почему жёсткие диеты не работают'), 'Резкое ограничение калорий организм читает как голод: замедляется обмен, теряются мышцы, обостряется тяга к еде. Отсюда срыв и возврат веса с запасом. Работает медленное изменение привычек: одна перемена за раз, 0,5–1 кг в неделю, белок и овощи в каждом приёме, нормальный сон. Диета, которую невозможно соблюдать год, не сработает.', 'питание, диета, похудение'),
  ('Сколько нужно двигаться', public.iskra_kb_norm('Сколько нужно двигаться'), 'ВОЗ: 150–300 минут умеренной активности в неделю (быстрая ходьба, велосипед) или 75–150 минут интенсивной, плюс силовые упражнения два раза в неделю. Это 20–40 минут в день, и их можно разбивать на куски по 10. Главное — регулярность: три прогулки в неделю лучше, чем один героический поход в зал в месяц.', 'спорт, активность, здоровье'),
  ('Тренировка дома без инвентаря', public.iskra_kb_norm('Тренировка дома без инвентаря'), 'Три круга: приседания 15, отжимания (с колен, если трудно) 8–12, планка 30–45 секунд, выпады на каждую ногу 10, ягодичный мостик 15. Отдых между упражнениями 30–45 секунд, между кругами 1–2 минуты. Занимайся 3 раза в неделю, а между ними ходи пешком. Прогресс — не больше повторений каждый день, а плюс одно повторение в неделю.', 'спорт, тренировка, дом'),
  ('Разминка перед тренировкой', public.iskra_kb_norm('Разминка перед тренировкой'), '5–10 минут общего разогрева: суставная гимнастика, лёгкое кардио до тёплого состояния и несколько движений из самой тренировки без веса. Статическую растяжку до силовой лучше не делать — она временно снижает силу. После тренировки — 3–5 минут спокойного темпа, чтобы пульс опустился.', 'спорт, разминка, травмы'),
  ('Боль в мышцах после тренировки', public.iskra_kb_norm('Боль в мышцах после тренировки'), 'Крепатура — тупая боль через 24–72 часа после новой или тяжёлой нагрузки, это норма. Помогает лёгкое движение, сон, вода, еда с белком. Не тренируй ту же группу мышц, пока не отпустит. Тревожные признаки: резкая боль в суставе, хруст, отёк, тёмная моча после нагрузки — это к врачу, а не «пройдёт».', 'спорт, мышцы, крепатура'),
  ('Растяжка: когда и сколько', public.iskra_kb_norm('Растяжка: когда и сколько'), 'Растягивайся после тренировки или отдельным занятием, а не вместо разминки. На одну мышцу — 30 секунд, спокойно, до лёгкого натяжения, без пружины и боли. Дыхание не задерживай. Гибкость растёт от регулярности: 5–10 минут почти каждый день лучше, чем час раз в неделю.', 'спорт, растяжка, гибкость'),
  ('Сколько восстанавливаться после тренировки', public.iskra_kb_norm('Сколько восстанавливаться после тренировки'), 'Одной группе мышц нужно 48 часов отдыха, поэтому силовые на всё тело — 2–3 раза в неделю, а не каждый день. Сон 7–9 часов — главное средство восстановления, еда с белком — второе. Признаки перетрена: пульс в покое выше обычного, пропал аппетит, не спится, тренировки стали тяжелее при том же весе. Тогда неделя отдыха, а не «ещё усилие».', 'спорт, восстановление, отдых'),
  ('Головная боль: что делать', public.iskra_kb_norm('Головная боль: что делать'), 'Сначала простые причины: мало воды, недосып, голод, духота, экран, стресс. Проветри, попей, поешь, отдохни в тишине. Обезболивающее — по инструкции и не чаще указанного, злоупотребление даёт обратный эффект. Срочно в скорую: внезапная «самая сильная боль в жизни», боль с температурой и негнущейся шеей, после удара головой, с онемением, нарушением речи или зрения.', 'здоровье, голова, боль'),
  ('Осанка и спина', public.iskra_kb_norm('Осанка и спина'), 'Идеально ровно сидеть весь день невозможно и не нужно: вредна не поза, а неподвижность. Вставай каждые 40–60 минут на 2–3 минуты, меняй положение. Монитор — на уровне глаз, стопы на полу, локти под углом около 90°. Сильные мышцы спины и пресса помогают больше, чем корсет. Боль, отдающая в ногу, онемение или слабость — к врачу.', 'здоровье, спина, осанка, сидячая работа'),
  ('Экран и зрение', public.iskra_kb_norm('Экран и зрение'), 'Правило 20-20-20: каждые 20 минут смотри 20 секунд на объект в 6 метрах. Экран — на расстоянии 50–70 см, верхний край чуть ниже уровня глаз, без бликов от окна и лампы. Яркость подстраивай под комнату. Сухость и жжение — от того, что реже моргаешь; капли и режим — по назначению врача. Регулярная проверка зрения раз в 1–2 года.', 'здоровье, зрение, экран'),
  ('Как ухаживать за зубами', public.iskra_kb_norm('Как ухаживать за зубами'), 'Чистить два раза в день по две минуты пастой с фтором 1450 ppm, щёткой с мягкой щетиной, аккуратно у десны. Нитью — ежедневно, в местах, куда щётка не достаёт. Сахар между приёмами пищи вреднее, чем в составе еды. Осмотр и чистка у стоматолога раз в полгода. Кровоточивость дёсен — это не «норма», а повод к врачу.', 'здоровье, зубы, гигиена'),
  ('Общий анализ крови: что смотреть', public.iskra_kb_norm('Общий анализ крови: что смотреть'), 'Ориентиры у взрослых примерные: гемоглобин 130–160 г/л у мужчин и 120–140 у женщин, лейкоциты 4–9, тромбоциты 150–400, СОЭ до 10–15. Но нормы у каждой лаборатории свои, и по одному отклонению диагноз не ставят. Сдают натощак, утром. Результат читает врач вместе с жалобами: сам по себе бланк ничего не значит.', 'здоровье, анализ, кровь'),
  ('Когда звонить в скорую', public.iskra_kb_norm('Когда звонить в скорую'), 'Номера 103 и 112. Звони сразу при: боли или давящем чувстве в груди, нехватке воздуха, потере сознания, онемении половины лица или тела, нарушении речи, сильном кровотечении, судорогах, отравлении, тяжёлой аллергии с отёком. Не вези сам, если человек без сознания или задыхается. Диспетчеру говори адрес, что случилось и возраст, коротко и по делу.', 'здоровье, скорая, экстренно'),
  ('Как повесить полку на стену', public.iskra_kb_norm('Как повесить полку на стену'), 'Сначала проверь, что в стене: в бетоне и кирпиче — дюбель 6–8 мм и саморез, в гипсокартоне — дюбель-бабочка или крепление в профиль. Проверь скрытую проводку и трубы (в панельных домах идут вертикально и горизонтально). Сверлить плитку — без режима удара. Отверстия размечай по самой полке, а не по памяти: уровень и карандаш экономят вторую дырку.', 'дом, ремонт, полка, дрель'),
  ('Подтекает кран', public.iskra_kb_norm('Подтекает кран'), 'Перекрой воду (вентиль на стояке или под раковиной), подставь таз. У обычного крана чаще всего изношена прокладка или кран-букса, у однорычажного — картридж: их меняют целиком, это дешевле новой сборки. Снимай аккуратно и запоминай порядок деталей — лучше сфотографировать. Если течёт соединение под раковиной или не откручивается — сантехник дешевле затопления.', 'дом, ремонт, кран, сантехника'),
  ('Плесень в ванной', public.iskra_kb_norm('Плесень в ванной'), 'Плесень живёт там, где влажно и нет движения воздуха. Сначала причина: проветривание после душа, работающая вытяжка, сушка белья не в ванной. Поражённую затирку и силикон лучше убрать и заменить, а не закрашивать. Обработка — специальным средством или перекисью, в перчатках и с открытым окном. Если плесень лезет постоянно — проверь вентиляцию.', 'дом, плесень, ванная, влажность'),
  ('Как покрасить стену', public.iskra_kb_norm('Как покрасить стену'), 'Порядок: убрать пыль → зашпаклевать трещины и дать высохнуть → прогрунтовать → оклеить края малярным скотчем и закрыть пол плёнкой. Красить валиком в два тонких слоя, а не один толстый; между слоями 2–4 часа по инструкции. Ведро не разбавляй водой без надобности. Температура в комнате выше 10 °C, без сквозняка. Кистью проходят углы и края.', 'дом, ремонт, покраска'),
  ('Засор в раковине', public.iskra_kb_norm('Засор в раковине'), 'Сначала вантуз: накрой перелив мокрой тряпкой и качай. Потом сантехнический трос. Кипяток с содой и уксусом помогает от жира и мыла, но не от волос. Химию не смешивай с другой химией и не лей в унитаз вместе с тросом. Засор в мойке с сифоном часто разбирается за две минуты — ведро под низ обязательны.', 'дом, засор, канализация'),
  ('Давление в шинах', public.iskra_kb_norm('Давление в шинах'), 'Обычно 2,0–2,4 бар, точное значение — на табличке в проёме водительской двери или в лючке бензобака. Меряй на холодных шинах: после поездки цифры выше на 0,2–0,3. Проверяй раз в месяц и перед дальней дорогой. Если одно колесо спускает быстрее остальных — ищи прокол или плохой ниппель, а не подкачивай ежедневно.', 'автомобиль, шины, давление'),
  ('Как проверить масло в двигателе', public.iskra_kb_norm('Как проверить масло в двигателе'), 'Машина на ровной площадке, двигатель заглушён 10 минут. Вытащи щуп, протри, вставь до конца, вытащи и смотри уровень: между метками — норма, ниже нижней — долей. Цвет: тёмное — нормально, чёрное густое — пора менять. Лампа давления масла на приборке значит «заглуши немедленно», а не «доеду до дома».', 'автомобиль, масло, двигатель'),
  ('Аккумулятор зимой', public.iskra_kb_norm('Аккумулятор зимой'), 'На морозе ёмкость падает, поэтому старый аккумулятор чаще всего умирает именно зимой. Не оставляй машину с разряженным аккумулятором и на долгой стоянке с сигнализацией. Провода для прикуривания: сначала плюс к плюсу, потом минус к массе, снимать в обратном порядке. Срок службы обычно 4–5 лет, и первым признаком становится тяжёлый запуск на холоде.', 'автомобиль, аккумулятор, зима'),
  ('Что делать при ДТП', public.iskra_kb_norm('Что делать при ДТП'), 'Остановись, включи аварийку, выставь знак (15 м в городе, 30 м за городом). Не уезжай — это уже оставление места ДТП. Проверь, нет ли пострадавших, при них звони 112. Дальше: фото повреждений и места с разных ракурсов, данные второго участника и полис, потом ГИБДД и страховщик. Если все целы и разногласий нет, оформляй европротокол по ОСАГО.', 'автомобиль, дтп, осаго'),
  ('Когда менять шины', public.iskra_kb_norm('Когда менять шины'), 'Зимнюю резину ставят при устойчивой среднесуточной температуре ниже +7 °C, летнюю — когда выше. Летние на морозе дубеют и тормозят хуже; зимние на тепле стираются. Шипованную нельзя долго держать на сухом асфальте. Храни комплект в сухом месте: летом — в чехлах, без прямого солнца; давление в хранении чуть выше обычного.', 'автомобиль, шины, сезон'),
  ('НДФЛ: сколько платим', public.iskra_kb_norm('НДФЛ: сколько платим'), 'С 2025 года налог на доходы физлиц в России прогрессивный: 13% при годовом доходе до 2,4 млн рублей, дальше 15%, 18%, 20% и 22% на самые высокие суммы. Работодатель удерживает налог сам, в справке видна сумма. Обычная зарплата у большинства — 13%. С продажи квартиры или машины налог считается отдельно и зависит от срока владения.', 'деньги, налоги, ндфл'),
  ('Налоговый вычет: как вернуть деньги', public.iskra_kb_norm('Налоговый вычет: как вернуть деньги'), 'Вычет — возврат части уплаченного НДФЛ. Бывают за лечение, обучение, спорт, покупку жилья и проценты по ипотеке, за инвестиции. Социальные вычеты (лечение, обучение, спорт) ограничены 150 000 рублей расходов в год, кроме дорогого лечения — там лимита нет. Оформляется через Госуслуги и личный кабинет ФНС, декларация 3-НДФЛ подаётся до 30 апреля следующего года.', 'деньги, налоги, вычет'),
  ('Самозанятость: как это работает', public.iskra_kb_norm('Самозанятость: как это работает'), 'Налог на профессиональный доход: 4% при оплате от физлица и 6% от юрлица, отчётности нет, взносы добровольные. Лимит — 2,4 млн рублей дохода в год. Регистрация в приложении «Мой налог» или на Госуслугах за пару минут, чек формируется там же и отправляется клиенту. Нельзя нанимать работников и перепродавать чужие товары — это уже не НПД.', 'деньги, работа, самозанятость'),
  ('Квитанция ЖКХ: что проверять', public.iskra_kb_norm('Квитанция ЖКХ: что проверять'), 'Показания счётчиков передают до 25 числа месяца, иначе начислят по нормативу. В квитанции проверь: площадь, число жильцов, тарифы, начисления за содержание и отопление. Если уезжал надолго — возможен перерасчёт за воду и вывоз мусора по заявлению. Долг растёт пенями, а с длительным долгом могут ограничить коммунальные услуги. Ошибку оспаривай в управляющей компании письменно.', 'деньги, жкх, квитанция'),
  ('Как выбрать вклад', public.iskra_kb_norm('Как выбрать вклад'), 'Сравнивай не только ставку, но и: срок, капитализацию процентов, условия досрочного снятия (часто проценты теряются), минимальную сумму и автопродление. Смотри на эффективную ставку с капитализацией, а не на рекламные «до». Вклады застрахованы АСВ до 1,4 млн рублей на человека в одном банке. Длинный вклад под высокий процент невыгоден, если деньги могут понадобиться.', 'деньги, вклад, банк'),
  ('Компьютер тормозит', public.iskra_kb_norm('Компьютер тормозит'), 'Открой диспетчер задач и посмотри, что грузит процессор и диск. Убери лишнее из автозагрузки. Проверь свободное место на системном диске: меньше 10% — тормоза, особенно без SSD. Установи обновления, проверь на вирусы. «Ускорители» и «чистильщики реестра» из рекламы только мешают. Если диск постоянно загружен на 100% — скорее всего пора менять на SSD.', 'компьютер, windows, скорость'),
  ('Установка программ без вирусов', public.iskra_kb_norm('Установка программ без вирусов'), 'Скачивай только с официального сайта или из магазина приложений, не с «сайтов-архивов» и без «кряков». При установке снимай галочки с дополнительных программ и смени браузерную страницу. Смотри имя издателя в свойствах файла. Windows Defender для дома достаточно, второй антивирус обычно вреден. После установки проверь список программ и удали то, что не просил.', 'компьютер, программы, вирусы'),
  ('Обновления Windows', public.iskra_kb_norm('Обновления Windows'), 'Обновления закрывают дыры в безопасности, поэтому их ставят регулярно, а не «когда-нибудь». После установки нужна перезагрузка — отложенная на месяцы накапливает ошибки. Перед крупным обновлением сохрани важное на внешний диск. Если обновление ломает драйвер — откати его через «Центр обновления» → «История обновлений». Не отключай обновления насовсем.', 'компьютер, windows, обновления'),
  ('Флешка: какая файловая система', public.iskra_kb_norm('Флешка: какая файловая система'), 'FAT32 читается везде, но файл больше 4 ГБ не поместится — подходит для музыки и мелких файлов. exFAT — без ограничения 4 ГБ и тоже работает на Windows, macOS и телевизорах: лучший выбор для обычной флешки. NTFS — только Windows и с правами доступа. Форматирование стирает всё: сначала скопируй нужное.', 'компьютер, флешка, файлы'),
  ('Забыл пароль Windows', public.iskra_kb_norm('Забыл пароль Windows'), 'Если учётная запись привязана к Microsoft, пароль сбрасывается на сайте через телефон или другой компьютер — потом вход по новому паролю. Для локальной учётной записи поможет заранее созданный диск сброса пароля или контрольные вопросы. Без них восстановление — только с потерей данных или переустановкой. Поэтому пароль восстановления настраивают сразу, а не после.', 'компьютер, windows, пароль'),
  ('Куда сохранять файлы', public.iskra_kb_norm('Куда сохранять файлы'), 'Документы, картинки и загрузки — по своим папкам, а не на рабочем столе: рабочий стол не резервируется и легко теряется при переустановке. Имя файла — дата и суть: «2026-03-01 договор аренды». Версии не перезаписывай, а добавляй к имени «v2». Храни копию в облаке или на внешнем диске: один диск — это не копия, а один шанс потерять всё.', 'компьютер, файлы, порядок'),
  ('Основные формулы Excel', public.iskra_kb_norm('Основные формулы Excel'), 'СУММ (SUM), СРЗНАЧ (AVERAGE), МИН/МАКС, СЧЁТЕСЛИ (COUNTIF), СУММЕСЛИ (SUMIF), ЕСЛИ (IF), ВПР или XLOOKUP для поиска по таблице. Доллар в ссылке ($A$1) фиксирует ячейку, чтобы не съехала при копировании. Ошибки: #ЗНАЧ! — не тот тип, #Н/Д — не нашлось значение, ###### — узкий столбец. Начинай формулу с = и проверяй её на двух-трёх строках.', 'компьютер, excel, таблицы'),
  ('Сводная таблица в Excel', public.iskra_kb_norm('Сводная таблица в Excel'), 'Данные должны быть одной таблицей с заголовками, без пустых строк и объединённых ячеек. Вставка → сводная таблица. Строки — то, по чему группируешь (месяц, категория), столбцы — второй разрез, значения — что считаем (сумма, количество). Сводная не обновляется сама: правая кнопка → «Обновить». Исходные данные она не меняет.', 'компьютер, excel, сводная'),
  ('Word: стили и оглавление', public.iskra_kb_norm('Word: стили и оглавление'), 'Не делай заголовки крупным шрифтом вручную — применяй стили «Заголовок 1», «Заголовок 2». Тогда оглавление вставляется само и обновляется одной кнопкой, а навигация по документу работает. Нумерация страниц — в колонтитулах. Перед отправкой: «Проверка» → орфография, и сохранить в PDF для получателя, чтобы вёрстка не поехала.', 'компьютер, word, документы'),
  ('Как учить иностранные слова', public.iskra_kb_norm('Как учить иностранные слова'), 'Учи слова в контексте, а не списком: фраза запоминается лучше отдельного перевода. Повторяй по интервалам — через день, три, неделю; для этого есть приложения вроде Anki. 10–20 новых слов в день достаточно, больше — и не запомнится. Произноси вслух: то, что проговорил, вспоминается быстрее. Повторяй старые слова, иначе они уходят за месяц.', 'языки, слова, память'),
  ('Английские времена: минимум', public.iskra_kb_norm('Английские времена: минимум'), 'Present Simple — привычки: I work. Present Continuous — сейчас: I am working. Past Simple — законченное прошлое: I worked. Present Perfect — результат к настоящему: I have worked (важен опыт или результат, время не названо). Future — will или going to. Начни с этих пяти — на них держится 80% бытовой речи, остальные добавятся по мере практики.', 'языки, английский, времена'),
  ('Английское произношение', public.iskra_kb_norm('Английское произношение'), 'В английском есть звуки, которых нет в русском: th, короткий и долгий гласный (ship и sheep), w и v. Русские буквы в транскрипции («сори» вместо sorry) закрепляют ошибку — лучше слушай озвучку в словаре и повторяй за диктором. Читай вслух по 5 минут в день. Ставь ударение в словах правильно: запоминай слово со звуком, а не с написанием.', 'языки, английский, произношение'),
  ('Немецкие артикли', public.iskra_kb_norm('Немецкие артикли'), 'В немецком три рода: der (мужской), die (женский), das (средний). Род не выводится из смысла, поэтому слово учат сразу с артиклем: der Tisch, die Lampe, das Fenster. В Akkusativ der меняется на den, в Dativ — на dem/der. Множественное число — всегда die. Ошибка в артикле не мешает понять смысл, поэтому не бойся говорить, пока учишь.', 'языки, немецкий, артикли'),
  ('Как поливать комнатные растения', public.iskra_kb_norm('Как поливать комнатные растения'), 'Поливай по состоянию почвы, а не по расписанию: палец на 2–3 см в грунт — сухо, пора. Вода комнатной температуры и отстоянная. Лучше реже и обильно, чем часто по чуть-чуть: корни должны тянуться вниз. Обязателен дренаж и отверстия в горшке — застой воды губит быстрее засухи. Зимой полив сокращают почти для всех.', 'растения, полив, дом'),
  ('Свет для комнатных растений', public.iskra_kb_norm('Свет для комнатных растений'), 'Большинству нужен яркий рассеянный свет: южное окно — много солнца, северное — мало. Признаки нехватки: вытянутые бледные побеги, мелкие листья, растение тянется к стеклу. Признаки ожога: сухие пятна на листьях у южного окна. Зимой и на северной стороне помогает фитолампа на 10–12 часов в день. Переставляй растение постепенно, а не сразу на солнце.', 'растения, свет, дом'),
  ('Пересадка комнатного растения', public.iskra_kb_norm('Пересадка комнатного растения'), 'Новый горшок на 2–4 см шире старого, с отверстиями. Лучшее время — весна и начало лета. На дно — дренаж, грунт подходящий виду. Растение вынимают вместе с комом, старый грунт стряхивают не полностью, корни расправляют. После пересадки — полив и две недели без подкормки и прямого солнца. Если горшок стал тесным, корни лезут из отверстий — пора.', 'растения, пересадка, дом'),
  ('Почему желтеют листья', public.iskra_kb_norm('Почему желтеют листья'), 'Нижние листья по одному желтеют и сохнут — естественное старение, это норма. Массово желтеют и вянут — чаще всего перелив и застой воды. Бледные листья и вытянутые побеги — мало света. Кончики сохнут — сухой воздух, жёсткая вода или нехватка питания. Сквозняк и холодный подоконник тоже дают жёлтые листья. Меняй один фактор за раз, иначе не поймёшь причину.', 'растения, листья, уход'),
  ('Чем кормить кошку', public.iskra_kb_norm('Чем кормить кошку'), 'Кошка — хищник, основа рациона — мясо или готовый корм класса не ниже «холистик/супер-премиум» с мясом первым ингредиентом. Молоко взрослым кошкам не нужно: от него бывает расстройство. Рыба каждый день — не для кошки, в ней много фосфора. Вода рядом с едой всегда, особенно на сухом корме. Порция — по весу и указанию на упаковке, а не «сколько съест».', 'животные, кошка, корм'),
  ('Чем кормить собаку', public.iskra_kb_norm('Чем кормить собаку'), 'Готовый корм по возрасту и размеру породы либо сбалансированный натуральный рацион, составленный с ветеринаром. Опасно: трубчатые кости, шоколад, виноград и изюм, лук и чеснок, алкоголь, ксилит из жвачки. Смена корма — за 5–7 дней, подмешивая новый. Вода всегда. Со стола не корми: это и лишний вес, и попрошайничество, и испорченный аппетит.', 'животные, собака, корм'),
  ('Прививки животным', public.iskra_kb_norm('Прививки животным'), 'Котят и щенков вакцинируют серией с интервалом, затем ревакцинация ежегодно. Обязательная для всех — от бешенства, плюс комплексная от вирусных инфекций. До окончания курса щенка не выгуливают там, где ходят другие собаки. За 10–14 дней до прививки — обработка от паразитов, иначе вакцинация не даст эффекта. Дату и название вакцины записывай в паспорт.', 'животные, прививки, ветеринар'),
  ('Когда с животным к врачу', public.iskra_kb_norm('Когда с животным к врачу'), 'Срочно: отказ от еды дольше суток, многократная рвота или понос с кровью, тяжёлое дыхание, судороги, отравление, кот не может сходить в туалет (это угрожает жизни за сутки). Планово: вялость, потеря веса, зуд и залысины, запах изо рта, изменения в поведении. Не давай человеческие лекарства без назначения: парацетамол и ибупрофен для кошек смертельны.', 'животные, ветеринар, здоровье'),
  ('СНИЛС и ИНН: в чём разница', public.iskra_kb_norm('СНИЛС и ИНН: в чём разница'), 'СНИЛС — номер лицевого счёта в системе пенсионного страхования, он один на всю жизнь и не меняется при смене фамилии. ИНН — номер налогоплательщика, тоже постоянный. СНИЛС нужен для работы, пенсии и льгот, ИНН — для налогов, бизнеса и многих заявлений. Оба номера не секретны, но и раздавать их в интернете без нужды не стоит. Получить и посмотреть можно на Госуслугах.', 'документы, снилс, инн'),
  ('Прописка: регистрация по месту жительства', public.iskra_kb_norm('Прописка: регистрация по месту жительства'), 'Постоянная регистрация оформляется по месту, где живёшь постоянно; временная — если уехал больше чем на 90 дней в другой город. Оформляют через Госуслуги, МФЦ или паспортный стол, нужен собственник и его согласие. Жить без регистрации дольше разрешённого срока — штраф. Снятие с учёта происходит автоматически при новой регистрации.', 'документы, прописка, госуслуги'),
  ('Справки через Госуслуги', public.iskra_kb_norm('Справки через Госуслуги'), 'Через Госуслуги получают: справку о доходах, об отсутствии судимости, выписку из ЕГРН, сведения о пенсионных накоплениях, налоговые уведомления. Электронная справка с усиленной подписью равнозначна бумажной, её принимают организации. Сроки разные: от нескольких минут до 30 дней (судимость). Скачивай PDF на телефон и в облако — потом проще найти.', 'документы, госуслуги, справки'),
  ('Электронная подпись', public.iskra_kb_norm('Электронная подпись'), 'Усиленная квалифицированная подпись (УКЭП) — юридический аналог собственной, нужна для сделок и отчётности. Простая (УНЭП) подходит для заявлений на Госуслугах. Для обычного человека часто достаточно приложения «Госключ»: подпись в телефоне, без токена. Сертификат имеет срок действия, продлевать надо заранее. Храни токен отдельно от компьютера — потеря означает перевыпуск.', 'документы, подпись, госуслуги'),
  ('Как читать сложную книгу', public.iskra_kb_norm('Как читать сложную книгу'), 'Сначала прочитай аннотацию и оглавление — пойми, о чём книга и как устроена. Не бросай после первой главы: у многих авторов разгон медленный. Читай с карандашом: пометки и вопросы на полях работают лучше перечитывания. Непонятные места пропускай, к ним вернёшься. После книги перескажи главное в трёх предложениях — если не получается, прочитал зря.', 'книги, чтение, учёба'),
  ('Как слушать классическую музыку', public.iskra_kb_norm('Как слушать классическую музыку'), 'Начни с известного и мелодичного: «Времена года» Вивальди, «Щелкунчик» Чайковского, «Картинки с выставки» Мусоргского, Вальсы Штрауса. Слушай одну вещь целиком несколько раз — знакомое слышится иначе. Обращай внимание на контрасты: громко и тихо, быстро и медленно — на них держится форма. Концерт в зале даёт больше, чем запись в наушниках, если есть возможность.', 'музыка, классика, искусство'),
  ('Как выбрать фильм', public.iskra_kb_norm('Как выбрать фильм'), 'Смотри на режиссёра и жанр, а не только на рейтинг: высокий балл у популярного блокбастера и у медленной драмы значит разное. Прочитай одну-две рецензии, но не спойлеры. Определи настроение: хочется думать, смеяться или отвлечься — от этого и выбирай. Смотреть без телефона в руке: половина фильма делается в деталях. Не понравилось за 20 минут — можно выключить, это не экзамен.', 'кино, фильмы, выбор')
